using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.Animations;using UnityEditor.SceneManagement;using LWS.TruckSports.Editor;
namespace LWS.TruckFieldGoal.Editor {
public static class FieldGoalCrowdAuthoring {
 const string Root="Assets/TruckFieldGoal/Crowd";
 public static void Upgrade(){var scene=EditorSceneManager.OpenScene(FieldGoalAuthoring.Scene);Install(UnityEngine.Object.FindAnyObjectByType<FieldGoalMatch>());EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
 static AnimationClip Clip(string name)=>AssetDatabase.LoadAllAssetsAtPath("Assets/UTS_FullPack/Models/People/Animations/Girl no Heel/"+name+".FBX").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__"));
 public static void Install(FieldGoalMatch match){var prior=match.GetComponent<FieldGoalCrowd>();if(prior!=null&&prior.authoredVersion>=6){foreach(var item in match.gameObject.scene.GetRootGameObjects())if(item.name.StartsWith("Union Field audience"))item.name="Union Field audience · shared Taxi characters";return;}if(prior!=null){var owned=GameObject.Find("Union Field audience · shared Taxi characters");if(owned!=null)UnityEngine.Object.DestroyImmediate(owned);UnityEngine.Object.DestroyImmediate(prior);}Directory.CreateDirectory(Root);var root=new GameObject("Union Field audience · shared Taxi characters").transform;var crowd=match.gameObject.AddComponent<FieldGoalCrowd>();crowd.match=match;crowd.authoredVersion=6;var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Root+"/Stadium reactions.controller");if(controller==null)controller=AnimatorController.CreateAnimatorControllerAtPath(Root+"/Stadium reactions.controller");foreach(var pair in new[]{("Idle","idle1_f"),("Cheer","cheer_f"),("Disappointed","idle2_f"),("Run","run_f"),("Shout","shout_f"),("Throw","work_assembly_f"),("Dance","dance_f")}){var existing=controller.layers[0].stateMachine.states.FirstOrDefault(s=>s.state.name==pair.Item1).state;if(existing==null)existing=controller.AddMotion(Clip(pair.Item2));existing.name=pair.Item1;existing.motion=Clip(pair.Item2);EditorUtility.SetDirty(existing);}EditorUtility.SetDirty(controller);
  var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/TruckPedestrianPlowing/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).OrderBy(p=>p).ToArray();if(paths.Length==0)throw new InvalidOperationException("Existing Taxi character variants are required for the stadium audience.");var prefabs=paths.Take(8).Select(AssetDatabase.LoadAssetAtPath<GameObject>).ToArray();var matrices=new List<Matrix4x4>[prefabs.Length];for(int i=0;i<matrices.Length;i++)matrices[i]=new List<Matrix4x4>();var actors=new List<Animator>();var stands=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Include).Where(r=>r.name=="Union Field Grandstand tier").OrderBy(r=>r.bounds.center.x).ThenBy(r=>r.bounds.center.y).ToArray();if(stands.Length<8)throw new InvalidOperationException("The actual Union Field stands must be present.");int number=0;
  foreach(var stand in stands)for(int row=0;row<4;row++)for(int seat=0;seat<72;seat++){var point=stand.transform.TransformPoint(new Vector3(Mathf.Lerp(-.47f,.47f,seat/71f),.505f,Mathf.Lerp(-.36f,.36f,row/3f)));var facing=Quaternion.LookRotation(Vector3.ProjectOnPlane(new Vector3(0,point.y,point.z)-point,Vector3.up));int who=number++%prefabs.Length;if(row==1&&seat>=34&&seat<38){var actor=SportsAudienceAuthoring.Spawn(prefabs[who],root,point,new Vector3(0,point.y,point.z),controller,1.25f);actor.runtimeAnimatorController=controller;actor.cullingMode=AnimatorCullingMode.CullCompletely;foreach(var r in actor.GetComponentsInChildren<Renderer>())r.shadowCastingMode=ShadowCastingMode.Off;actors.Add(actor);}else matrices[who].Add(Matrix4x4.TRS(point,facing,Vector3.one*1.25f));}
  crowd.nearFans=actors.ToArray();crowd.batches=new FieldGoalCrowd.Batch[prefabs.Length];for(int i=0;i<prefabs.Length;i++){var actor=SportsAudienceAuthoring.Spawn(prefabs[i],root,Vector3.zero,Vector3.forward,controller,1);actor.runtimeAnimatorController=controller;var idle=Bake(actor,"Idle",Root+"/Fan "+i+" idle.asset",out var mats);var cheer=Bake(actor,"Cheer",Root+"/Fan "+i+" cheer.asset",out _);crowd.batches[i]=new FieldGoalCrowd.Batch{idle=idle,cheer=cheer,materials=mats,seats=matrices[i].ToArray()};var batch=crowd.batches[i];batch.fans=new MeshFilter[batch.seats.Length];for(int n=0;n<batch.seats.Length;n++){var fan=new GameObject("Pooled instanced posed fan "+i+" · "+n);fan.transform.SetParent(root,false);var pose=batch.seats[n];fan.transform.SetPositionAndRotation(pose.GetColumn(3),pose.rotation);fan.transform.localScale=pose.lossyScale;batch.fans[n]=fan.AddComponent<MeshFilter>();batch.fans[n].sharedMesh=idle;var render=fan.AddComponent<MeshRenderer>();render.sharedMaterials=mats;render.shadowCastingMode=ShadowCastingMode.Off;render.receiveShadows=false;}UnityEngine.Object.DestroyImmediate(ActorRoot(actor,root).gameObject);}
  var runner=SportsAudienceAuthoring.Spawn(prefabs[0],root,new Vector3(34,0,-27),new Vector3(24,0,-27),controller,1);crowd.runner=ActorRoot(runner,root);crowd.runnerAnimator=runner;runner.runtimeAnimatorController=controller;crowd.runner.gameObject.SetActive(false);var audio=new GameObject("Event driven stadium response").AddComponent<AudioSource>();audio.transform.SetParent(root,false);audio.playOnAwake=false;audio.loop=false;audio.spatialBlend=0;crowd.response=audio;crowd.cheer=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");crowd.boo=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Playful crowd boo.wav");if(crowd.cheer==null||crowd.boo==null)throw new InvalidOperationException("Owned crowd response clips missing.");FieldGoalAnticsAuthoring.Install(crowd,root,controller);EditorUtility.SetDirty(crowd);
 }
 static Transform ActorRoot(Animator actor,Transform parent){var result=actor.transform;while(result.parent!=null&&result.parent!=parent)result=result.parent;return result;}
 static Mesh Bake(Animator actor,string state,string path,out Material[] materials){actor.cullingMode=AnimatorCullingMode.AlwaysAnimate;actor.Rebind();var controller=(AnimatorController)actor.runtimeAnimatorController;var clip=(AnimationClip)controller.layers[0].stateMachine.states.First(s=>s.state.name==state).state.motion;clip.SampleAnimation(actor.gameObject,clip.length*.37f);var root=actor.transform;while(root.parent!=null&&root.parent.name!="Union Field audience · shared Taxi characters")root=root.parent;var groups=new Dictionary<Material,List<CombineInstance>>();var temporary=new List<Mesh>();foreach(var renderer in root.GetComponentsInChildren<Renderer>(true)){if(!renderer.enabled||!renderer.gameObject.activeInHierarchy)continue;Mesh mesh=null;if(renderer is SkinnedMeshRenderer skin){mesh=new Mesh();skin.BakeMesh(mesh);temporary.Add(mesh);}else if(renderer.GetComponent<MeshFilter>() is MeshFilter filter)mesh=filter.sharedMesh;if(mesh==null)continue;for(int i=0;i<Mathf.Min(mesh.subMeshCount,renderer.sharedMaterials.Length);i++){var mat=renderer.sharedMaterials[i];if(mat==null)continue;if(!groups.TryGetValue(mat,out var instances)){instances=new List<CombineInstance>();groups.Add(mat,instances);}instances.Add(new CombineInstance{mesh=mesh,subMeshIndex=i,transform=root.worldToLocalMatrix*renderer.transform.localToWorldMatrix});}}
  var parts=new List<CombineInstance>();var owned=new List<Material>();foreach(var pair in groups){var part=new Mesh{indexFormat=IndexFormat.UInt32};part.CombineMeshes(pair.Value.ToArray(),true,true);temporary.Add(part);parts.Add(new CombineInstance{mesh=part,transform=Matrix4x4.identity});string matPath=Root+"/Instanced "+pair.Key.name.Replace('/','_')+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(mat==null){mat=new Material(pair.Key);AssetDatabase.CreateAsset(mat,matPath);}mat.enableInstancing=true;EditorUtility.SetDirty(mat);owned.Add(mat);}var result=new Mesh{name=Path.GetFileNameWithoutExtension(path),indexFormat=IndexFormat.UInt32};result.CombineMeshes(parts.ToArray(),false,true);result.RecalculateBounds();var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(result,path);saved=result;}else{EditorUtility.CopySerialized(result,saved);UnityEngine.Object.DestroyImmediate(result);EditorUtility.SetDirty(saved);}foreach(var mesh in temporary)UnityEngine.Object.DestroyImmediate(mesh);materials=owned.ToArray();return saved;
 }
}
}
